const { sortQuery } = require('./dist/index.cjs');

// Test cases
const tests = [
  { input: '/foo?b=2&a=1&c=3#top', expected: '/foo?a=1&b=2&c=3#top' },
  { input: 'http://example.com/?z=1&y=2', expected: 'http://example.com/?y=2&z=1' },
  { input: '/foo', expected: '/foo' },
  { input: '/path?single=value', expected: '/path?single=value' },
  { input: 'http://foo.com/path?z=3&a=1&m=2#hash', expected: 'http://foo.com/path?a=1&m=2&z=3#hash' },
];

let passed = 0;
for (const test of tests) {
  const result = sortQuery(test.input);
  if (result === test.expected) {
    console.log('✓', test.input);
    passed++;
  } else {
    console.log('✗', test.input);
    console.log('  Expected:', test.expected);
    console.log('  Got:', result);
  }
}

console.log(\`\n\${passed}/${tests.length} tests passed\`);
"

